-- items: 18817, 18818
function event_say(e)
	if(e.message:findi("hail")) then
		e.self:Say("Greetings, citizen! You should not be in the Militia House. These are restricted grounds. Please leave at once unless you have business here.");
	elseif(e.message:findi("truth is good") and e.other:Class() == "Paladin") then
		e.self:Say("Ssshhh!! Pipe down. The others might hear you. You must have something for me. Kalatrina must have given you something if you serve the Hall of Truth. If you have nothing please leave. You will blow my cover.");
	end
end

function event_trade(e)
	local item_lib = require("items");

	if(e.other:Class() == "Paladin") then
		if(item_lib.check_turn_in(e.trade, {item1 = 18817})) then -- Sealed Letter
			e.self:Say("This is not good news. I must leave immediately. Here. Take this to Kala.. I mean my father. I found it on the floor of Sir Lucan D'Lere's quarters. Thanks again, messenger. I got this just in time.");
			e.other:SummonItem(18818); -- A Tattered Flier
			e.other:Ding();
			e.other:Faction(311,1,0); -- Steel Warriors
			e.other:Faction(262,1,0); -- Guards of Qeynos
			e.other:Faction(230,-1,0); -- Corrupt Guards of Qeynos
			e.other:Faction(330,-1,0); -- Freeport Militia
			e.other:Faction(281,1,0); -- Knights of Truth
			eq.unique_spawn(382245,56,0,820,-931,-23,256); -- spawns Krazen Loosh
		end
	end
	item_lib.return_items(e.self, e.other, e.trade)
end

function event_signal(e)
	e.self:Say("'Oh no!! It is too late!! Run!!");
	eq.signal(382245,1,5000); -- NPC: Krazen_Loosh
end

-- freeporteast version - Guard_Alayle

function event_combat(e)
	if e.joined then
			if(not eq.is_paused_timer("despawn")) then
				eq.pause_timer("despawn");
			end
		eq.set_timer('Hardblur', 180 * 1000);
		eq.set_timer('Softblur', 6 * 1000);
	else
		eq.stop_timer('Hardblur');
		eq.stop_timer('Softblur');
		eq.resume_timer("despawn");
		e.self:SaveGuardSpot(e.self:GetX(),e.self:GetY(), e.self:GetZ(), e.self:GetHeading()); 
	end
end


function event_timer(e)
	if (e.timer == 'Hardblur') then
		e.self:WipeHateList();
	elseif (e.timer == 'Softblur') then
		if (math.random(100)<=5) then
			e.self:WipeHateList();
		end
	elseif (e.timer == "despawn") then
			eq.stop_timer("despawn");
			eq.depop();
	end
end


function event_spawn(e)
	eq.set_timer("despawn", 2700 * 1000);
	e.self:Shout("Leave now foolish mortal you have begun to send events in motion that you cannot possibly understand!");
end

function event_death_complete(e)
eq.signal(215455,3); -- NPC: #Mist_Trigger
end

-- will despawn while in combat if timer is met

function event_spawn(e)
  eq.set_timer("depop", 2700 * 1000); -- 45 min uptime
end


function event_timer(e)
  if (e.timer == "depop") then
    eq.depop_with_timer();
  end
end

-- items: 22298, 13279, 13121, 22293, 22294, 22295, 22296, 22297, 22299
function event_say(e)
	if e.message:findi("hail") then
		e.self:Say("Greetings. I would love to chat with you, but I just realized something.. I do not waste time with whelps.");
	elseif e.message:findi("lens") then
		e.self:Say("So you seek the Spare Lens. Yes. I have it. There are only two ways you can obtain it, [fight] the great Zenita or [play a game of chance].");
	elseif e.message:findi("play a game of chance") then
		e.self:Say("Great. It is rather simple. I have five cards and only one is King Naythox. Find it. In order to get one card all you need to do is buy me a bottle of Innoruuks Kiss of Death from the barkeep in Chops N Hops. One bottle for one card. Return the King Naythox card to me and you shall get the Spare Lens.");
	elseif e.message:findi("fight") then
		e.self:Say("Darn!! I was hoping not to hear that word, fight. Oh well.");
		eq.attack(e.other:GetName());
	end
end

function event_trade(e)
	local item_lib = require("items");
	if item_lib.check_turn_in(e.trade, {item1 = 22298}) then
		e.self:Say("Why I will be.. You got it!! I thought I took it out of the deck. Very well. You win the Spare Lens fair and square. Here you are. Now get out of my sight.");
		e.other:SummonItem(13279); -- Phiz's lens
		e.other:Ding();
		e.other:AddEXP(500);
	elseif item_lib.check_turn_in(e.trade, {item1 = 13121}) then
		e.self:Say("Let see what card you pulled.");
		e.other:SummonItem(eq.ChooseRandom(22293,22294,22295,22296,22297,22298,22299)); -- Item(s): Castle Card (22293), Beggar Card (22294), Joker Card (22295), Wild Card (22296), Queen Card (22297), King Card (22298), Knight Card (22299)
	elseif item_lib.check_turn_in(e.trade, {item1 = 22299} or {item1 = 22297} or {item1 = 22296} or {item1 = 22294} or {item1 = 22293}) then
		e.self:Say(string.format("Bad luck must be one of your strong suits. You should have been a beggar because you sure aren't a very good %s. You lose!",e.other:Class()));
	elseif item_lib.check_turn_in(e.trade, {item1 = 22295}) then
		e.self:Say(string.format("I see you have drawn the card that best represents a %s such as yourself. You lose!",e.other:GetRaceName()));
	end
	item_lib.return_items(e.self, e.other, e.trade)
end

