local event_counter = 0;
local event_mobs = {223087,223226,223111,223120,223240,223241}; 

--specify trial boundaries for player check routine
local min_x = -75;
local max_x = 90;
local min_y = 1290;
local max_y = 1415;
local player_limit = 18;	

function event_spawn(e)
