		e.self:Say("The spirit saw that Undari always wore a beautiful necklace made of polished stone that her mother gave her. Her mother was taken by the trusik long ago because she refused to accept Trushar into her heart. She was taken down to the shores of Natimbi and shackled, sentenced to hang over the sea until she died. It was then that the spirit chose to bestow a [" .. eq.say_link("great gift") .. "] on Undari, as thanks and reward for her steadfast faith in the spirit world.");
	elseif(e.message:findi("great gift") and qglobals["shaman_epic"] == "10") then
		e.self:Say("'The spirit appeared before Undari, who was overcome with humility. The spirit cast a mighty spell and it rained upon Undari and was imbued into her necklace. The necklace would henceforth protect the young Undari from those who held dark beliefs and would try to corrupt her mind. Now you see why we had need of this necklace. But we are not done yet. We still need to make a [" .. eq.say_link("talisman") .. "].");
	elseif(e.message:findi("talisman") and qglobals["shaman_epic"] == "10") then
		e.self:Say("Yes, we need to complete a talisman to perform the Ruchu and it is up to us to finish this part of the task. We need a particular type of wood and it is rather unusual. You shall only find this material in an ethereal plane where the woods are imbued with spirits. I am counting on you to hunt down a sample of this wood and show it to me when you've acquired it.");		
	end
end

function event_trade(e)
	local item_lib = require("items");
	local qglobals = eq.get_qglobals(e.other);
	if(qglobals["shaman_epic"] == "9" and item_lib.check_turn_in(e.trade, {item1 = 57401})) then --hand in Necklace of Perseverance (looted from Ikaav Spiritstealer in KT)
		e.self:Say("You have traveled far, my friend. This necklace is more powerful than those foolish Muramites knew. Undari has been holding a key to the spirit world around her neck for many years. How do you think she remained [" .. eq.say_link("protected") .. "] near those temples and beasts?");
		eq.set_global("shaman_epic","10",5,"F");
	end
	if(qglobals["shaman_epic"] == "10" and item_lib.check_turn_in(e.trade, {item1 = 57403})) then -- hand in Piece of Moaning Timber (looted from a Darkened Chanting Woodspirit in Plane of Storms)
		e.self:Say("You have done well," .. e.other:GetName() .. ". We are drawing nearer to being fully prepared for the Ruchu. I've put the bark and the necklace into this satchel that is protected by a spell. The only one who may open it is the Spirit of Enlightenment. Go and give that to it.");
